            new GossipText(1, 1, "Greetings, stranger. You startled me, but that's nothing new around here...", new GossipCondition(12, 20, false)),
            new GossipText(25, 1, "What? I've got nothin' else to say to ya, pal.\n\nHead down the road here, the priests' house isn't far.", new GossipCondition(1, 20, true)),
            new GossipText(11, 2, "<$NPC$ appears to be sizing you up.>\n\nSay now, $PLAYER$...\nAre you lookin' for some quick gold? \n\nNo tricks, on my honor.", new GossipCondition(12, 9, false), new GossipCondition(12, 7, false), new GossipCondition(2, 1, true)),
            new GossipText(12, 2, "Well met, $PLAYER$. How are you?", new GossipCondition(12, 9, true)),
            new GossipText(13, 2, "Well met, $PLAYER$. How are you?", new GossipCondition(12, 7, true)),
            new GossipText(279, 2, "Greetings, stranger. Name's $NPC$, a sword for hire. I'm not surprised to see your kind here. Many $class$'s have traveled this way since the recent troubles began.\n\nDo you need any help?", new GossipCondition(2, 1, false)),
            new GossipText(4, 3, "Come, sit with me for a moment, $PLAYER$. ", new GossipCondition(1, 22, true), new GossipCondition(3, 22, false)),
            new GossipText(7, 3, "Glad to hear it, $PLAYER$.", new GossipCondition(1, 22, true), new GossipCondition(3, 22, true)),
            new GossipText(5, 4, "Wealth comes in many forms. Food, health and a good home. That's true wealth.\n\nHowever, a few years ago, things started to change..."),
            new GossipText(6, 5, "Some say we had it too good for too long. Others say the gods turned their backs on us...\n\n<Vincent hesitates - his eyes seem lost, troubled by something.>"),
            new GossipText(8, 6, "To think that Lord Revere, the god of Hope and Prosperity, has left us... blasphemous.\n\n<Vincent gazes at the campfire, perhaps talking to himself more than you.>\n\nNo, there is something else going on, but I do not wish to put myself inbetween the Council and the Church of St. Revere."),
            new GossipText(9, 7, "That's exactly correct, $PLAYER$. I have a good feeling about you, my $G=boy:girl$. I can tell instantly about people, it's a gift.\n\nWhat do you say?"),
            new GossipText(256, 8, "Why hello fine traveler, how do you fare on such a lovely day?\n\n<The goblin sounds like an eccentric middle aged man but looks and speaks with the accent of an elder>\n\nBillings' the name, $G=my good sir:my lady$. A pleasure to meet you.\nA young $G=lad:lass$ like yourself must be looking for fortune!\n\nHm? Is something on your mind, then?", new GossipCondition(3, 108, true)),
            new GossipText(258, 8, "Ah, back again are you? I see, I see. \nI've become quite popular, wouldn't you agree?\n\n<$NPC$ chuckles faintly under his breath>", new GossipCondition(2, 109, true), new GossipCondition(2, 110, true), new GossipCondition(2, 111, true)),
            new GossipText(267, 8, "You're in luck my dear $G=boy:girl$. \nI have much coin and you have much need.\n\nUnanswered questions...\nWhat a nuisance that would be.", new GossipCondition(2, 109, true)),
            new GossipText(268, 8, "<$NPC$ seems preoccupied with something>"),
            new GossipText(20, 9, "Yeah? Who are you and what do you want?\n\n<Emitt looks right through you, clearly unimpressed>\n\nIf you're another Fechmar messenger then you better tuck tail and get out of here before you get on my nerves.", new GossipCondition(12, 101, false), new GossipCondition(12, 102, false), new GossipCondition(2, 100, false)),
            new GossipText(75, 9, "Yeah, what is it?\n\n<Emitt sighs impatiently>\n\nZedek doesn't pay me enough for this."),
            new GossipText(239, 10, "Yes, what business have you?", new GossipCondition(2, 103, false)),
            new GossipText(240, 10, "My, my, my... '$PLAYER$', was it?\n\n<$NPC$ is playing with his beard as he eyes you with an eccentric smile>\n\nI think that we will become most good friends.\nMost good friends, indeed.", new GossipCondition(2, 103, true), new GossipCondition(12, 104, false), new GossipCondition(12, 105, false)),
            new GossipText(241, 10, "<$NPC$ sighs>\n\nYes?", new GossipCondition(1, 107, true)),
            new GossipText(261, 10, "What the...", new GossipCondition(3, 106, true)),
            new GossipText(262, 10, "Ah, if it isn't my favorite $class$.\nWell then, $PLAYER$ - what business have you?"),
            new GossipText(89, 11, "I really hope Crescent Lake becomes safe again soon...\n\n<$NPC$ sighs sadly>\n\nWhere else am I going to gather my beautiful Cheryb Flowers?"),
            new GossipText(91, 12, "Ah, $PLAYER$. How are ye?\n\n<Darius shows you the new harness hes made>\n\nSee? Nice, eh?\n\nThanks again for helping out.", new GossipCondition(2, 28, true)),
            new GossipText(93, 12, "What can I do for ya, $class$?"),
            new GossipText(104, 13, "Stand away traveler."),
            new GossipText(109, 14, "Move along now, St. Revere isn't far, just follow the road and the guard outposts will lead the way."),
            new GossipText(112, 15, "Move along now, St. Revere isn't far, just follow the road and the guard outposts will lead the way."),
            new GossipText(117, 16, "Move along now, St. Revere isn't far, just follow the road and the guard outposts will lead the way."),
            new GossipText(121, 17, "Move along now, St. Revere isn't far, just follow the road and the guard outposts will lead the way."),
            new GossipText(207, 18, "Hail traveler, good to see you."),
            new GossipText(123, 19, "The Lord watches over us, friend, even when the road seems darkest.\n\nSome say it's a test of our faith."),
            new GossipText(124, 20, "Welp, unfortunately the meeting really didn't shed any light on anything... I guess we'll have to continue our investigation while Leon keeps the council happy. I'll keep an eye on Azralus in the meantime...", new GossipCondition(2, 118, true), new GossipCondition(2, 119, true)),
            new GossipText(135, 20, "I wish I could tell you more, but for now it's the hurry up and wait game. Bureaucracy and politics can be a dangerous game, and I'm not a very good player.\n\nI will let you know when something happens. I'll keep an eye on Azralus in the meantime...", new GossipCondition(2, 122, true)),
            new GossipText(136, 20, "Always stay alert, you never know what can happen... especially now.\n\n<Lamuel gives you a nod of respect.>"),
            new GossipText(127, 21, "<Thaddeus' eyebrows are gone and the hair in the front of his head is missing.>\n\nIts always good to try new experiments to come up with new and useful products, even if sometimes they blow up in your face.\n\n<Thaddeus smiles.>", new GossipCondition(2, 33, true), new GossipCondition(2, 34, true)),
            new GossipText(128, 21, "<You see Thaddeus poking a needle at some sort of bloody object.>\n\nGreetings, good master. I am Thaddeus, the apothecary."),
            new GossipText(129, 22, "<Arjay pays no attention to you as he mumbles inaudibly and writes in his log book.>", new GossipCondition(2, 32, true)),
            new GossipText(130, 22, "Hello. I am Arjay, the lead Inspector for the town."),
            new GossipText(131, 23, "I just know my family will love the new house, $PLAYER$. I can't wait to get started!", new GossipCondition(2, 35, true)),
            new GossipText(132, 23, "Good day, my friend, I'm Lawrence, the local builder. You know the Church of Revere? My great great great grandfather built that with his brother, hundreds of years ago."),
            new GossipText(133, 24, "<Briggs sighs.>\n\nWith all this recent trouble, its making this job much more stressful. I used to be able to just perch here on the wall and read all day, now there's an interruption every few minutes...\n\nI knew I should've taken that cushy sargeant job when I had the chance... but it wasn't even any extra pay....\n\n<Briggs mumbles off.>", new GossipCondition(2, 120, true)),
            new GossipText(134, 24, "<Briggs is reading his book.>\n\nIf you're ever looking for a good book, the library on the other side of town is stocked. The librarian's name is Tessa, nice gal, quite the looker too...\n\n<Briggs winks.>"),
            new GossipText(137, 25, "<Regal grips his keychain on his belt.>\n\nI'm going to try to only take duty inside the town from now on... I'm honestly too afraid to step outside the walls anymore...", new GossipCondition(2, 43, true)),
            new GossipText(138, 25, "Be careful when travelling outside of town... Its not like it used to be."),
            new GossipText(143, 26, "Hey there, you look thirsty. \n\nDo you want to try some freshly brewed beer?", new GossipCondition(7, 277, false, "Drunk")),
            new GossipText(270, 26, "I think you've had enough, $PLAYER$...", new GossipCondition(7, 277, true, "Drunk")),
            new GossipText(145, 27, "I'll always have a good business here. \n\nPeople are always willing to pay for a quick fix to a complex problem. \n\nI had a gentleman come in last week looking for a potion that would keep him young forever... I told him to stop visiting drinking ten ales every day."),
            new GossipText(146, 28, "Didn't I already pay you? Sorry, but I'm busy concocting here and I can't be interrupted, else something might blow up!", new GossipCondition(2, 41, true)),
            new GossipText(152, 28, "Good day, my friend! Isn't this a beautiful day? Perfect for just about any adventure!"),
            new GossipText(147, 29, "Run along now, little one.\n\nI may be blind but I'm not dumb. That Vincent... found another prodigy, has he?\n\n<$NPC$ scoffs>\n\nYou're weak, $PLAYER$. I can sense that much. Come back some other time.", new GossipCondition(15, 7, false)),
            new GossipText(269, 29, "$PLAYER$, is that you?", new GossipCondition(15, 7, true), new GossipCondition(2, 27, true)),
            new GossipText(151, 30, "Remember, don't wash your mushrooms until you're ready to use them, else they get mushy and inedible.", new GossipCondition(12, 40, true)),
            new GossipText(154, 30, "Hello, stranger! Are you hungry? My name is Jacques and I'm the best chef on this island.\n\nDon't believe me? Just ask around, but not Zedek."),
            new GossipText(155, 31, "Zedek asked me to be his head chef, but I told him I wasn't interested, so he doesn't like me too much.\nI don't think very much of him either, his father was a much better man and actually did a lot of good for this town.\n\nI'm bot sure waht happened to him, but I do remember as a child he always seemed like a good kid.\n\nNow all he cares about is money and power.\n\n<Jacques shrugs.>"),
            new GossipText(158, 32, "Howdy, stranger! Hows it going? Silveroak Park is the right place for some peace and quiet. I work to make sure everything is neat and clean.\n\nSee those statues over there?\n\n<Kent turns and points at the statues>\n\nThey honor the founding fathers of St. Revere."),
            new GossipText(160, 33, "Good day, stranger, I think I've heard about you. Your name is $PLAYER$, right? I'm Vivien.\n\n<You watch Vivien as she carefully assembles a book, being very impressed by her skilful work>\n\nAs you can see, I make books. I just love the smell and sound of flipping through the pages a new book, theres nothing else like it."),
            new GossipText(161, 34, "May Zorn guide you on your journey, $PLAYER$. If you wish to become a follower of Zorn, we can make that happen.", new GossipCondition(2, 47, true)),
            new GossipText(164, 34, "Greetings, Stranger. What brings you here? Not a lot of people come to this place. This is the Altar of Zorn and I am here to serve Zorn, the God of the earth and elements."),
            new GossipText(165, 35, "<Jamil stands up tall as you approach.>\n\nWelcome to our little saltwater fishing community. I hope you're not a bandit."),
            new GossipText(166, 36, "We live here not only because it’s close to the ocean, but also because we don't wish to serve Revere. We are welcome to go there to Saint Revere to trade or sell our fish, but other than that we like to keep to ourselves."),
            new GossipText(168, 37, "Hi I'm Garett, and I'm a professional angler. I've been fishing all my life, and I love it."),
            new GossipText(173, 38, "Good day, friend. You look well-traveled, so I’m guessing you’re not one of those idiots from St. Revere. My name is Tybalt. Lived on this island my whole life."),
            new GossipText(175, 39, "<Julya is fixing her chef's apron.>\n\nHello, I am Julya, an apprentice to Jacques. I do all his prep work and manage the kitchen. I hope one day I can be as skilled as he is. "),
            new GossipText(177, 40, "Hi I'm Nina. Nice to see new faces around here.\n\nI can't say that it happens very often."),
            new GossipText(182, 41, "Things are really looking grim around here... \n\nTo tell the you the truth, if I didn't have a young son, I'd be out of this place."),
            new GossipText(184, 42, "Well now... a $class$.\n\n<The scar faced man gazes at you>\n\nYou're in the wrong neck of the woods.\n\n$NPC$'s the name. I'm a big-game hunter, plain as. \nThat's Piotr... little bugger's been following me since St. Revere, but he's harmless enough.\n\nJust set up camp here this morning.\nWell then, $PLAYER$... what can I do for you?"),
            new GossipText(187, 43, "Howdy, stranger.\n\n<The goblin's voice is shockingly deep with an accent not from around here>\n\nYou alright there, big fella'?\nWhat, you ain't never seen a goblin before or somethin'?\n\nHey, listen pal - I follow the money. You might be thinking, \"now how are you gonna find coin way out here\"... and yet, I see a transaction in my future. Imagine that."),
            new GossipText(191, 45, "Hi, I'm Herdith. I'm looking for wild mushrooms. They can be quite tasty and can be useful in a lot of different medicine. You need to be careful though, because the wrong mushroom can make you very ill or even send you to the grave! If you have questions about which mushroom is okay to eat, just let me know!"),
            new GossipText(193, 46, "I miss my husband..."),
            new GossipText(197, 47, "Good day, friend. You look like you’ve been getting about quite a bit. Welcome to our little community. We don’t get a lot of visits from strangers here. My name is Jordy and you could say I'm a healer."),
            new GossipText(200, 48, "Wow! A new face! Did you get lost and end up here like I did? I barely escaped from those bastard zombies... unbelievable, but now I'm stuck here..."),
            new GossipText(202, 49, "Hey there, how ye doin? You got any news for us? Is the world out there fallin' apart or what?"),
            new GossipText(203, 50, "<Samel becomes wide-eyed.>\n\nOh geez... you really think so? Well... I'm not sure, but if you can make it all the way here, we should probably group and flee before it's too late... but again... uhhh.. I dunno maybe we should here instead... it looks pretty rough out there."),
            new GossipText(204, 51, "Yes.. you're right. We should stay here and ride it out.\n\nMaybe that Azralus guy was right and I should've attended church as a kid..."),
            new GossipText(216, 52, "<You notice Yoan's face looks a bit jaundiced.>\n\nOhh... I just can't seem to shake this fever and chills...\n\nJordy is trying to come up with a solution. My wife is sicker than I am and in bed."),
            new GossipText(215, 53, "<Miriam is mumbling to herself... something about a cat.>"),
            new GossipText(212, 54, "My name is Frederic... Doctor Frederic. \n\nMy passion is natural medicine... flora and fauna... there are many strange and wonderful things that occur in nature, but nobody takes the time to really look and study."),
            new GossipText(219, 55, "Please, don't be afraid. I am Dante and I used to be a priest of the Church of Revere and an elder of the town. As you can see, my physical life is over, but my soul refuses to rest."),
            new GossipText(220, 56, "I was out here a few weeks ago visting the cemetery, when a foul zombie jumped out of the bushes and stabbed me with some wretched weapon. He quickly ran off, but I recognized him as Goresh, a defier of the Church of Revere and enemy of the townsfolk. Goresh and his followers were executed several years ago by the council of Revere, which I oversaw at the time. As a result of the attack, I am stuck here, seemingly forever. "),
            new GossipText(221, 57, "<You take a big sip of beer from a mug she hands you and rub your belly in satisfaction>"),
            new GossipText(223, 58, "Hi, I'm Grover. My time is spent running around this town delivering messages. \n\nIt's good pay, but I get tired. I eat muffins all day long to give me energy. Alaria is quite the baker, you should pay her a visit!"),
            new GossipText(227, 59, "Begone peasant, before I call the guards."),
            new GossipText(229, 60, "You ever seen an exploding Antling? Well I have! I made two last week in my basement!"),
            new GossipText(234, 61, "What's this? A mortal being? What do you think you're doing here $G=boy:girl$? Perhaps... you are suicidal, or perhaps you seek me out. I guess we will find out.\n\n<Mastemia smiles at you.>"),
            new GossipText(236, 62, "Hey there feller, welcome to my farm. I'm a generous guy but don't be stealing anything! "),
            new GossipText(238, 63, "Through this entrance is the Eversorrow Forest. You should stay out unless you know what you're doing."),
            new GossipText(243, 64, "Oh? About what?"),
            new GossipText(248, 65, "Did they now? \n\nWell I very seriously doubt that it had anything to do with the flower. It's a very common and plain flower. \n\nA run of bad luck is all, but nothing you couldn't handle.\nThe right $G=man:woman$ for the job, indeed!\n\n<$NPC$'s attempts to sound cheery are labored at best>"),
            new GossipText(245, 66, "I honestly haven't a clue. Well, just that...\n\n<$NPC$ thinks for a moment>\n\nI overheard a drunkard at the Inn of St. Revere blathering about the undead. Nothing new there, but he insisted they're cunning deceivers. How did he put it... \"they're tricky snakes playing us for fools!\", he shouted. \n\nHe wasn't alone, but I didn't linger."),
            new GossipText(246, 67, "The man claimed, ah - how did he put it...\n\n<$NPC$ plays with his beard as he quotes the drunkard>\n\n\"I was mindin' me own business. That's when I seen 'em beyond the trees. Watching the guards. Tallest undead I ever  seen. Looked me in the eyes, he did. When the guard called my name... it just up'n left, calm and cold as ice!\"\n\nHe said it happened on the road near the Ruins of At'mar."),
            new GossipText(247, 68, "How the hell should I know?!\n\n<$NPC$'s tone is quiet but stern>\n\nThe undead attack us. \nWhat difference does it make if they're deft or dull?\n\nI'll speak no more of it. I've told you all I know."),
            new GossipText(249, 69, "Nonsense. \n\nI'll speak no more."),
            new GossipText(250, 70, "Prefer? I'm left handed, but what do you mean?\n\n<$NPC$ seems notably concerned>\n\nWhat are you getting at?"),
            new GossipText(251, 71, "N-Now... there's no need for that.\n\n<$NPC$ is notably sweating>\n\nAlright, fine. The peddler that's buying these artifacts... he says that the undead are attracted to them.\n\nTotal nonsense I told myself!\nBut, well... I had to be sure, right?"),
            new GossipText(252, 72, "Yes... and that's all there is to it.\nHonestly, I thought it was nonsense and that no harm would come to you.\n\nWell then, satisfied?"),
            new GossipText(253, 73, "I'm glad that we had this little chat.\n\nBye now, $class$."),
            new GossipText(254, 74, "<$NPC$'s fright is obvious but he remains defiant>\n\nFie! I'm not lying. Listen, I didn't know for sure it would work. I had... a man I trust told me it was true, that he saw it himself. I just wanted to know what I was dealing with. \n\nThese artifacts are fetching a high price. Here, you can have them. I owe you that much. Fair?"),
            new GossipText(255, 75, "He calls himself Billings.\nIf you have a map then I will show you.\n\n<$NPC$ is relieved but clearly disappointed>"),
            new GossipText(260, 76, "Ah, heading for St. Revere? Well met, noble $CLASS$. \n\nI'm not surprised to see your kind here. Heard rumor of fortune, did you? Wouldn't mind some fortune, myself.\n\nJust follow the road directly south from here.\n\nI wouldn't recommend the road to the east. It'll get you there same, but I've heard unfriendly rumors about that route."),
            new GossipText(263, 100, "Good day to you, $G=sir:madam$.\n\nNice day, isn't it?"),
            new GossipText(264, 101, "Why, yes am I am. How could you tell?"),
